use std::borrow::Cow;

use gpui_kit::{AssetSource, Result, SharedString};

/// Bundled WhatsLite assets. GPUI Kit's own icon source is delegated to, so
/// `IconName::*` keeps working while Inter and Noto Emoji are served from the
/// application binary. The doodle wallpaper is generated by `build.rs`.
#[derive(Clone, Copy, Debug, Default)]
pub struct Assets;

impl AssetSource for Assets {
    fn load(&self, path: &str) -> Result<Option<Cow<'static, [u8]>>> {
        match path {
            "fonts/InterVariable.ttf" => Ok(Some(Cow::Borrowed(include_bytes!(
                "../assets/fonts/InterVariable.ttf"
            )))),
            "fonts/NotoEmoji-Regular.ttf" => Ok(Some(Cow::Borrowed(include_bytes!(
                "../assets/fonts/NotoEmoji-Regular.ttf"
            )))),
            _ => gpui_kit::assets::AllAssets.load(path),
        }
    }

    fn list(&self, path: &str) -> Result<Vec<SharedString>> {
        let mut entries = gpui_kit::assets::AllAssets.list(path)?;
        if "fonts/InterVariable.ttf".starts_with(path) {
            entries.push("fonts/InterVariable.ttf".into());
        }
        if "fonts/NotoEmoji-Regular.ttf".starts_with(path) {
            entries.push("fonts/NotoEmoji-Regular.ttf".into());
        }
        Ok(entries)
    }
}
